"""Canonical source manifest and content fingerprints."""

from __future__ import annotations

import hashlib
from typing import TYPE_CHECKING

from .config import ROOT

if TYPE_CHECKING:
    from pathlib import Path


def source_files() -> list[Path]:
    """Enumerate release inputs while excluding caches and generated bytecode."""
    files = [
        ROOT / name
        for name in (
            "readme.md",
            "pyproject.toml",
            "uv.lock",
            ".python-version",
            "Dockerfile",
            "Makefile",
            "compose.yaml",
            "compose.production.yaml",
            ".env.example",
            ".env.production.example",
            ".dockerignore",
            ".gitignore",
        )
    ]
    for directory in ("src", "scripts", "tests", "docs"):
        files.extend(
            p
            for p in (ROOT / directory).rglob("*")
            if p.is_file() and "__pycache__" not in p.parts and p.name != ".DS_Store"
        )
    return sorted(files)


def checksum(path: Path) -> str:
    """Stream a file into a SHA-256 digest."""
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def source_fingerprint() -> str:
    """Hash a path-sorted manifest of source-file checksums."""
    manifest = "".join(f"{checksum(p)}  {p.relative_to(ROOT).as_posix()}\n" for p in source_files())
    return hashlib.sha256(manifest.encode()).hexdigest()
